def _testlauf(werk: Path, dateien: dict[str, str]) -> tuple[bool, str]:
    """True = mindestens ein Test fällt (Mutant gefangen). Rückgabe (gefangen, fallende Tests)."""
    e = kammer.ausfuehren(werk, ["python", "-m", "pytest", "-q", "-p", "no:cacheprovider", "--tb=no", "-x", "-q"], zeitlimit_s=90, dateien=dateien)
    fallen = re.findall(r"^FAILED (\S+)", e.stdout, re.M)
    gefangen = e.rc != 0
    return gefangen, ", ".join(fallen[:3]) or ("Zeitlimit/Absturz" if gefangen and not fallen else "")

